-- Version 6's schema at user_version 7: the v7 delta (meal_ratings) belongs to the build that
-- merges first, so this branch upgrades a 6 or a 7 file straight to 8.
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE "ingredient_groups" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "kind" TEXT NOT NULL, "food_group" TEXT NOT NULL, "tracking_mode" TEXT NOT NULL, "stock_unit" TEXT NULL, "allowed_forms" TEXT NOT NULL, "unopened_shelf_life_days" TEXT NOT NULL, "once_opened_shelf_life_days" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "ingredients" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "canonical_name" TEXT NOT NULL UNIQUE, "api_name" TEXT NULL, "group_id" TEXT NULL REFERENCES ingredient_groups (id), "catalogue_item_id" TEXT NULL, "form" TEXT NULL, "canonical_unit" TEXT NULL, "is_staple" INTEGER NOT NULL DEFAULT 0 CHECK ("is_staple" IN (0, 1)), "store_section" TEXT NULL);
CREATE TABLE "pantry_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" TEXT NOT NULL, "ingredient_id" INTEGER NOT NULL REFERENCES ingredients (id), "quantity" REAL NOT NULL, "unit" TEXT NOT NULL, "unit_price" REAL NULL, "expiry_date" TEXT NULL, "last_used_at" TEXT NULL, "updated_at" TEXT NOT NULL, UNIQUE ("user_id", "ingredient_id"));
CREATE TABLE "recipes" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" TEXT NOT NULL, "external_id" TEXT NULL, "title" TEXT NOT NULL, "source_url" TEXT NULL, "cuisine" TEXT NULL, "difficulty" TEXT NULL, "active_time_mins" INTEGER NULL, "total_time_mins" INTEGER NULL, "not_suitable_for" TEXT NOT NULL DEFAULT '[]', "yield_count" INTEGER NULL, "nutrition" TEXT NULL, "instructions" TEXT NOT NULL DEFAULT '[]', "last_cooked_at" TEXT NULL, UNIQUE ("user_id", "external_id"));
CREATE TABLE "recipe_dietary_flags" ("recipe_id" INTEGER NOT NULL REFERENCES recipes (id) ON DELETE CASCADE, "flag" TEXT NOT NULL, PRIMARY KEY ("recipe_id", "flag"));
CREATE TABLE "recipe_ingredients" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "recipe_id" INTEGER NOT NULL REFERENCES recipes (id) ON DELETE CASCADE, "ingredient_id" INTEGER NOT NULL REFERENCES ingredients (id), "quantity" REAL NOT NULL, "unit" TEXT NOT NULL, "preparation" TEXT NULL, "is_optional" INTEGER NOT NULL DEFAULT 0 CHECK ("is_optional" IN (0, 1)), "substitutions" TEXT NOT NULL DEFAULT '[]');
CREATE TABLE "meal_plan_entries" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" TEXT NOT NULL, "recipe_id" INTEGER NULL REFERENCES recipes (id) ON DELETE SET NULL, "recipe_title" TEXT NOT NULL, "planned_date" TEXT NOT NULL, "cooked_at" TEXT NULL, "external_id_snapshot" TEXT NULL, "previous_recipe_cooked_at" TEXT NULL, "servings" INTEGER NOT NULL);
CREATE TABLE "cooked_adjustments" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" TEXT NOT NULL, "meal_plan_entry_id" INTEGER NOT NULL REFERENCES meal_plan_entries (id) ON DELETE CASCADE, "ingredient_id" INTEGER NOT NULL REFERENCES ingredients (id), "amount_deducted" REAL NOT NULL, "unit" TEXT NOT NULL, "previous_last_used_at" TEXT NULL, "created_at" TEXT NOT NULL);
CREATE TABLE "shopping_list_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" TEXT NOT NULL, "ingredient_id" INTEGER NOT NULL REFERENCES ingredients (id), "name" TEXT NOT NULL, "quantity" REAL NULL, "unit" TEXT NULL, "source" TEXT NOT NULL DEFAULT 'manual', "is_requirement" INTEGER NOT NULL DEFAULT 0 CHECK ("is_requirement" IN (0, 1)), "is_checked" INTEGER NOT NULL DEFAULT 0 CHECK ("is_checked" IN (0, 1)), "source_meal_plan_entry_id" INTEGER NULL REFERENCES meal_plan_entries (id) ON DELETE CASCADE);
CREATE TABLE "user_config" ("id" TEXT NOT NULL, "purchase_tolerance" REAL NOT NULL DEFAULT 0.5, "preferred_servings" INTEGER NOT NULL DEFAULT 2, "meals_per_week" INTEGER NOT NULL DEFAULT 5, "dietary_flags" TEXT NOT NULL DEFAULT '[]', "max_active_time_mins" INTEGER NULL, "onboarding_completed" INTEGER NOT NULL DEFAULT 0 CHECK ("onboarding_completed" IN (0, 1)), "group_shopping_by_section" INTEGER NOT NULL DEFAULT 0 CHECK ("group_shopping_by_section" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "catalogue_items" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "group_id" TEXT NOT NULL, "form" TEXT NOT NULL, "source" TEXT NOT NULL, "density_g_per_ml" REAL NULL, "override_tracking_mode" TEXT NULL, "override_stock_unit" TEXT NULL, "override_unopened_shelf_life_days" INTEGER NULL, "override_once_opened_shelf_life_days" INTEGER NULL, "section" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "catalogue_aliases" ("key" TEXT NOT NULL, "name" TEXT NOT NULL, "item_id" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "catalogue_sync_state" ("id" INTEGER NOT NULL, "version" INTEGER NOT NULL, "synced_at" TEXT NOT NULL, "full_synced_at" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "ingredient_overrides" ("item_id" TEXT NOT NULL, "tracking_mode" TEXT NULL, "stock_unit" TEXT NULL, "unopened_shelf_life_days" INTEGER NULL, "once_opened_shelf_life_days" INTEGER NULL, "section" TEXT NULL, PRIMARY KEY ("item_id"));
CREATE TABLE "catalogue_item_redirects" ("former_id" TEXT NOT NULL, "item_id" TEXT NOT NULL, PRIMARY KEY ("former_id"));
COMMIT;
PRAGMA user_version = 7;
